  js: R`
var W=480,H=600,GY=H-120,run=false,t=0,jarak=0,chips=0,py=GY,vy=0,duck=false,onG=true,obs=[],items=[],spd=6,lives=3,fx=0,dj=false,E=null,epN=1,heli=null;
window.__mulai=function(ep){epN=ep;E=G.eps[ep-1];run=true;window.__running=true;t=0;jarak=0;chips=0;py=GY;vy=0;onG=true;duck=false;dj=false;lives=3;obs=[];items=[];heli=E.bos?{x:W+80,y:120,cd:0}:null;spd=E.spd*[.85,1,1.15][SET.get().cepat];upd();dialog('EPISODE '+ep+' — '+E.judul,E.intro[E.intro.length-1])};
function upd(){I('jr').textContent=Math.floor(jarak)+'m';I('ch').textContent=chips;I('lv').textContent='❤'.repeat(Math.max(0,lives))}
function lompat(){if(!run||dopen||paused)return;if(onG){vy=-15;onG=false;dj=true;bip(500,.08,'square')}else if(dj){vy=-12;dj=false;bip(700,.08,'square')}}
function update(){if(!run||paused||dopen)return;t++;jarak+=spd/10;
 if(jarak>=E.target){run=false;return tamat(true,Math.floor(jarak)+chips*10)}
 vy+=.8;py+=vy;if(py>=GY){py=GY;vy=0;onG=true}
 var gap=Math.max(34,80-epN*6);if(t%gap===0){var r=Math.random(),tipe='kotak';if(E.kereta&&r<.3)tipe='kereta';else if(E.drone&&r<.5)tipe='drone';else if(E.semua){tipe=r<.25?'kereta':r<.5?'drone':r<.7?'jurang':'kotak'}else if(r>.75)tipe='jurang';obs.push({x:W+40,tipe:tipe,w:tipe==='kereta'?120:tipe==='jurang'?70:40,h:tipe==='drone'?30:tipe==='kereta'?50:44,y:tipe==='drone'?GY-70:tipe==='kereta'?GY-95:GY})}
 if(t%45===0)items.push({x:W+20,y:GY-40-Math.random()*90});
 if(heli){heli.x+=(W-110-heli.x)*.02;heli.cd--;if(heli.cd<=0){heli.cd=70;obs.push({x:heli.x,tipe:'bom',w:16,h:16,y:heli.y+30,vy:3})}}
 for(var j=obs.length-1;j>=0;j--){var o=obs[j];o.x-=spd;if(o.tipe==='bom'){o.y+=o.vy;if(o.y>GY){obs.splice(j,1);continue}}if(o.x<-150){obs.splice(j,1);continue}
  var ph=duck?24:48,ptop=py-ph,hit=false;
  if(o.tipe==='jurang'){if(onG&&py>=GY&&Math.abs((o.x+o.w/2)-30)<o.w/2-8)hit=true}
  else if(o.tipe==='bom'){if(Math.abs(o.x-30)<18&&o.y>ptop&&o.y<py)hit=true}
  else if(o.tipe==='kereta'||o.tipe==='drone'){if(44>o.x&&16<o.x+o.w&&ptop<o.y+o.h&&py>o.y)hit=true}
  else{if(44>o.x&&16<o.x+o.w&&py>o.y-o.h)hit=true}
  if(hit&&!o.kena&&fx<=0){o.kena=true;lives--;fx=40;getar(80);bip(120,.25,'sawtooth',.1);upd();if(lives<=0){run=false;return tamat(false,Math.floor(jarak)+chips*10)}}}
 for(var k=items.length-1;k>=0;k--){var c=items[k];c.x-=spd;if(c.x<-20)items.splice(k,1);else if(Math.abs(c.x-30)<20&&Math.abs(c.y-(py-24))<34){items.splice(k,1);chips++;bip(900,.06,'sine')}}
 if(fx>0)fx--;if(t%10===0)upd()}
function draw(){var g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,E&&E.gelap?'#000':'#05020f');g.addColorStop(1,E&&E.gelap?'#0a0a12':'#1a0a2e');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);var c=['#ff2bd6','#39ff14'];
 if(E&&E.bos){ctx.fillStyle='#ff9f43';ctx.beginPath();ctx.arc(W-80,GY-40,60,0,7);ctx.fill()}
 for(var i=0;i<14;i++){var bx=((i*90-(t*spd*.3))%(W+120)+W+120)%(W+120)-60,bh=120+((i*53)%160);ctx.fillStyle=E&&E.gelap?'#050508':'rgba(40,20,70,.9)';ctx.fillRect(bx,GY-bh,60,bh);if(!(E&&E.gelap)){ctx.fillStyle=c[0]+'55';for(var wy=GY-bh+10;wy<GY-10;wy+=18)for(var wx=bx+6;wx<bx+54;wx+=14)if((wx+wy+i)%3)ctx.fillRect(wx,wy,8,10)}}
 ctx.fillStyle='#0e0a1c';ctx.fillRect(0,GY,W,H-GY);ctx.strokeStyle=c[1];ctx.lineWidth=3;ctx.shadowColor=c[1];ctx.shadowBlur=14;ctx.beginPath();ctx.moveTo(0,GY);ctx.lineTo(W,GY);ctx.stroke();ctx.shadowBlur=0;
 obs.forEach(function(o){if(o.tipe==='jurang'){ctx.fillStyle='#000';ctx.fillRect(o.x,GY-2,o.w,H-GY);ctx.strokeStyle=c[0];ctx.strokeRect(o.x,GY-2,o.w,3)}else if(o.tipe==='bom'){ctx.fillStyle='#ff5f5f';ctx.beginPath();ctx.arc(o.x,o.y,8,0,7);ctx.fill()}else if(o.tipe==='drone'){ctx.fillStyle='#222';rr(o.x,o.y,o.w,o.h,8);ctx.fill();ctx.fillStyle='#ff2b2b';ctx.beginPath();ctx.arc(o.x+o.w/2,o.y+o.h/2,5+Math.sin(t*.3)*2,0,7);ctx.fill()}else if(o.tipe==='kereta'){ctx.fillStyle='#3a2a55';rr(o.x,o.y,o.w,o.h,10);ctx.fill();ctx.fillStyle=c[1];for(var q=0;q<4;q++)ctx.fillRect(o.x+10+q*28,o.y+12,18,14)}else{ctx.fillStyle='#2a1a44';rr(o.x,o.y-o.h,o.w,o.h,6);ctx.fill();ctx.strokeStyle=c[0];ctx.lineWidth=2;ctx.stroke()}});
 items.forEach(function(ch){ctx.fillStyle='#ffd84a';ctx.shadowColor='#ffd84a';ctx.shadowBlur=10;rr(ch.x-8,ch.y-8,16,16,4);ctx.fill();ctx.shadowBlur=0});
 if(heli){ctx.fillStyle='#222';rr(heli.x-40,heli.y,80,30,10);ctx.fill();ctx.fillStyle='#888';ctx.fillRect(heli.x-50,heli.y-6,100,4);ctx.fillStyle='#ff2b2b';ctx.fillRect(heli.x-6,heli.y+10,12,10)}
 var ph=duck?24:48;ctx.save();if(fx>0&&t%4<2)ctx.globalAlpha=.4;ctx.fillStyle='#111';rr(16,py-ph,28,ph,6);ctx.fill();ctx.fillStyle=c[1];ctx.fillRect(20,py-ph+8,20,4);ctx.fillStyle=c[0];ctx.fillRect(18,py-6,10,6);ctx.fillRect(32,py-6,10,6);ctx.restore();
 if(E&&E.gelap){ctx.fillStyle='rgba(0,0,0,.6)';ctx.fillRect(0,0,W,H);ctx.save();ctx.globalCompositeOperation='destination-out';var rg=ctx.createRadialGradient(30,py-24,20,30,py-24,200);rg.addColorStop(0,'rgba(0,0,0,.6)');rg.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=rg;ctx.fillRect(0,0,W,H);ctx.restore()}
 if(E){ctx.fillStyle='rgba(255,255,255,.7)';ctx.font='bold 11px monospace';ctx.textAlign='left';ctx.fillText('EP'+epN+' '+E.judul.toUpperCase(),12,20);ctx.textAlign='right';ctx.fillText(Math.floor(jarak)+' / '+E.target+' m',W-12,20);ctx.fillStyle='rgba(255,255,255,.15)';ctx.fillRect(12,28,W-24,4);ctx.fillStyle=c[1];ctx.fillRect(12,28,(W-24)*Math.min(1,jarak/E.target),4)}}
(function loop(){update();draw();requestAnimationFrame(loop)})();
tap('bJump',lompat);hold('bDuck',function(){duck=true},function(){duck=false});
document.addEventListener('keydown',function(e){if(e.key===' '||e.key==='ArrowUp')lompat();if(e.key==='ArrowDown')duck=true});document.addEventListener('keyup',function(e){if(e.key==='ArrowDown')duck=false});
`
