  tujuan: 'Capai kedalaman target tiap episode sebelum oksigen atau lambung habis.',
  tamat: 'Nadia menyentuh kaca kokpit Nautila-1. Di dalamnya, jurnal ayahnya masih terbuka di halaman terakhir: "Kalau Nadia yang menemukan ini — Ayah tidak pernah tersesat. Ayah hanya menunggu di tempat paling indah yang pernah Ayah lihat, supaya kau juga bisa melihatnya."',
  eps: [
    { judul: 'Sinyal dari Palung', target: 400, o2: .02, intro: ['Dua puluh tahun lalu kapal selam riset *Nautila-1* hilang di Palung Sunda. Pilotnya: *Dr. Arman* — ayahmu.', 'Kau *NADIA*, 27 tahun, dan minggu lalu stasiun riset menangkap sinyal pemancar lama dari kedalaman 2.400 meter. Frekuensinya milik Nautila-1.', '*DR. SARI* (mentor ayahmu): "Aku tidak bisa melarangmu, Nadia. Tapi turunlah pelan. Palung itu tidak memaafkan siapa pun."'], outro: ['400 meter. Sonar menangkap gema logam jauh di bawah. *DR. SARI*: "Itu… bukan batu. Nadia, aku rasa dia benar-benar ada di sana."'], gagal: 'Nautila-2 naik darurat ke permukaan. Dr. Sari menyambutmu tanpa sepatah kata, hanya pelukan.' },
    { judul: 'Bangkai Kapal Karam', target: 900, o2: .025, ikan: true, intro: ['Zona senja. Cahaya matahari tinggal ingatan. Di bawah ada bangkai kapal barang yang tenggelam tahun 1970-an.', 'Di sela-sela karat, kau menemukan pelampung penanda berlogo *Nautila*. Ayahmu pernah lewat sini.', '*DR. SARI*: "Ikan-ikan besar bersarang di bangkai. Mereka tertarik pada lampu. Matikan kalau perlu."'], outro: ['Di dinding bangkai kapal, tergores dengan pisau: "A. 2006 → ↓". Panah ke bawah. Tulisan tangan ayahmu. Kau menangis di dalam helm dan tidak bisa mengusapnya.'], gagal: 'Ikan pemangsa merobek baling-baling. Nautila-2 naik dengan sisa tenaga terakhir.' },
    { judul: 'Ladang Ubur-Ubur', target: 1500, o2: .03, ubur: true, intro: ['1.000 meter. Ribuan ubur-ubur bercahaya melayang seperti lentera yang lepas dari pesta yang sudah lama usai.', 'Rekaman audio ayahmu (tahun 2006) diputar dari pemancar: "…Sari, kau harus lihat ini. Ini seperti langit. Nadia pasti suka. Aku akan bawa dia ke sini suatu hari."', 'Kau di sini sekarang, Ayah.'], outro: ['Kau melewati ladang ubur-ubur dengan lambung penuh sengatan tapi hati yang anehnya ringan. Dia benar. Ini seperti langit.'], gagal: 'Sengatan ubur-ubur melumpuhkan sistem listrik. Nautila-2 hanyut, lalu pelampung darurat menariknya naik.' },
    { judul: 'Longsoran Palung', target: 2000, o2: .035, batu: true, intro: ['Dinding palung retak. Batu-batu sebesar rumah berjatuhan dalam gerak lambat.', '*DR. SARI*: "Nadia, log terakhir Nautila-1 dikirim dari sini. Longsoran ini… yang menjebaknya dua puluh tahun lalu."', '*NADIA*: "Maka aku akan lewat di tempat yang sama. Aku ingin tahu apa yang dia lihat terakhir kali."'], outro: ['Kau lolos dari longsoran. Sonar kini menunjukkan bentuk yang jelas 400 meter di bawah: sebuah kapal selam kecil, utuh, bersandar di lereng — dan sesuatu bercahaya biru di sekitarnya.'], gagal: 'Batu menghantam menara pengawas. Nautila-2 naik dengan jendela retak dan pilot yang berjanji akan kembali.' },
    { judul: 'Kota yang Tenggelam', target: 2400, o2: .04, semua: true, intro: ['2.000 meter. Lampu kapalmu menyentuh sesuatu yang tidak masuk akal: tiang, tangga, gerbang. Sebuah kota. Bercahaya biru dari dalam.', 'Nautila-1 bersandar di gerbangnya, seolah diparkir dengan hati-hati. Pemancarnya masih berkedip. Dua puluh tahun.', '*DR. SARI* (suara pecah): "Arman menemukannya. Dia menemukannya, dan dia memilih tinggal untuk menjaga sinyalnya tetap hidup — supaya seseorang bisa menyusul."'], outro: ['Kau mendarat di samping Nautila-1. Oksigenmu cukup untuk lima menit. Cukup untuk melihat ke dalam kokpit, dan cukup untuk mengucapkan satu kalimat yang tertunda dua puluh tahun: "Ayah, aku datang."'], gagal: 'Oksigen habis 200 meter dari gerbang kota. Pelampung darurat aktif. Kota biru itu mengecil di bawahmu — tapi sekarang kau tahu jalannya.' }
  ],
