var W=480,H=600,run=false,t=0,px=W/2,py=120,vx=0,vy=0,o2=100,hull=100,depth=0,skor=0,keys={},ent=[],bubbles=[],light=1,art=0,E=null,epN=1;
window.__mulai=function(ep){epN=ep;E=G.eps[ep-1];run=true;window.__running=true;t=0;px=W/2;py=120;vx=vy=0;ent=[];bubbles=[];keys={};o2=100;hull=100;depth=Math.max(0,(G.eps[ep-2]||{target:0}).target-50);art=0;skor=0;light=1;upd();dialog('EPISODE '+ep,E.intro[E.intro.length-1])};
function upd(){I('o2').textContent=Math.max(0,o2|0)+'%';I('hl').textContent=Math.max(0,hull|0)+'%';I('dp').textContent=Math.floor(depth)+'m'}
