  js: R`
var W=480,H=600,run=false,t=0,x=0,y=0,vx=0,vy=0,ang=-Math.PI/2,fuel=100,skor=0,thr=false,rl=false,rrt=false,stars=[],ast=[],hull=100,waktu=0,E=null,epN=1;
for(var i=0;i<90;i++)stars.push({x:Math.random()*W,y:Math.random()*H,r:Math.random()*1.6});
window.__mulai=function(ep){epN=ep;E=G.eps[ep-1];run=true;window.__running=true;t=0;x=E.dari.x;y=E.dari.y-E.dari.r-12;vx=vy=0;ang=-Math.PI/2;fuel=100;hull=100;waktu=0;skor=0;ast=[];for(var i=0;i<E.ast;i++)ast.push({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*.8,vy:(Math.random()-.5)*.8,r:8+Math.random()*10});upd();dialog('MISI '+ep+' — '+E.judul,E.intro[E.intro.length-1])};
function upd(){I('fu').textContent=Math.max(0,fuel|0)+'%';I('hl').textContent=Math.max(0,hull|0)+'%';I('sk').textContent=skor}
function update(){if(!run||paused||dopen)return;t++;waktu++;var sp=[.8,1,1.2][SET.get().cepat];
 if(rl)ang-=.06;if(rrt)ang+=.06;if(thr&&fuel>0){vx+=Math.cos(ang)*.08*sp;vy+=Math.sin(ang)*.08*sp;fuel-=.12;if(t%3===0)bip(80,.03,'sawtooth',.02)}
 var dx=E.ke.x-x,dy=E.ke.y-y,d=Math.hypot(dx,dy);vx+=dx/d*E.g*(120/Math.max(60,d));vy+=dy/d*E.g*(120/Math.max(60,d));
 if(epN===4){vx+=Math.sin(t*.02)*.02}
 x+=vx;y+=vy;if(x<0){x=0;vx*=-.5}if(x>W){x=W;vx*=-.5}if(y<0){y=0;vy*=-.5}if(y>H){y=H;vy*=-.5}
 for(var i=0;i<ast.length;i++){var a=ast[i];a.x+=a.vx;a.y+=a.vy;if(a.x<0||a.x>W)a.vx*=-1;if(a.y<0||a.y>H)a.vy*=-1;if(Math.hypot(a.x-x,a.y-y)<a.r+10){hull-=15;vx+=(x-a.x)*.1;vy+=(y-a.y)*.1;getar(60);bip(120,.2,'sawtooth',.08);if(hull<=0){run=false;return tamat(false,skor,'Asteroid merobek lambung Serayu-07. Pod penyelamat aktif.')}}}
 if(d<E.ke.r+12){var v=Math.hypot(vx,vy);run=false;if(v<1.2){var bonus=Math.max(0,300-Math.floor(waktu/10))+Math.floor(fuel)*2;skor=200+bonus;return tamat(true,skor)}return tamat(false,0,'Terlalu cepat ('+v.toFixed(2)+'). Paket hancur. '+(E.gagal||''))}
 if(t%10===0)upd()}
function draw(){ctx.fillStyle='#03050f';ctx.fillRect(0,0,W,H);stars.forEach(function(s){ctx.fillStyle='rgba(255,255,255,'+(.4+Math.sin(t*.05+s.x)*.3)+')';ctx.fillRect(s.x,s.y,s.r,s.r)});if(!E)return;
 if(epN===4){ctx.fillStyle='rgba(255,176,32,'+(.05+Math.sin(t*.1)*.03)+')';ctx.fillRect(0,0,W,H)}
 [E.dari,E.ke].forEach(function(p,i){var g=ctx.createRadialGradient(p.x-p.r*.3,p.y-p.r*.3,p.r*.2,p.x,p.y,p.r);g.addColorStop(0,'#fff');g.addColorStop(.2,p.c);g.addColorStop(1,'#000');ctx.fillStyle=g;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill();if(i===1){ctx.strokeStyle='rgba(255,216,74,.6)';ctx.setLineDash([4,6]);ctx.beginPath();ctx.arc(p.x,p.y,p.r+14,0,7);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#ffd84a';ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.fillText('TUJUAN',p.x,p.y-p.r-20)}});
 ast.forEach(function(a){ctx.fillStyle='#5a5a66';ctx.beginPath();ctx.arc(a.x,a.y,a.r,0,7);ctx.fill()});
 ctx.save();ctx.translate(x,y);ctx.rotate(ang+Math.PI/2);if(thr&&fuel>0){ctx.fillStyle='rgba(255,'+(120+Math.random()*100|0)+',40,.9)';ctx.beginPath();ctx.moveTo(-5,12);ctx.lineTo(0,22+Math.random()*12);ctx.lineTo(5,12);ctx.fill()}ctx.fillStyle='#dfe6f0';ctx.beginPath();ctx.moveTo(0,-14);ctx.lineTo(9,10);ctx.lineTo(-9,10);ctx.closePath();ctx.fill();ctx.fillStyle='#22c1ee';ctx.beginPath();ctx.arc(0,-2,3.5,0,7);ctx.fill();ctx.restore();
 var v=Math.hypot(vx,vy);ctx.fillStyle='rgba(0,0,0,.5)';rr(8,8,W-16,26,8);ctx.fill();ctx.fillStyle=v<1.2?'#3bff6b':'#ff5f5f';ctx.font='bold 11px sans-serif';ctx.textAlign='left';ctx.fillText('kecepatan '+v.toFixed(2)+(v<1.2?' ✓ aman':' ✗ terlalu cepat'),16,26);ctx.fillStyle='#fff';ctx.textAlign='right';ctx.fillText('MISI '+epN+' · '+E.judul,W-16,26)}
(function loop(){update();draw();requestAnimationFrame(loop)})();
hold('bL',function(){rl=true},function(){rl=false});hold('bR',function(){rrt=true},function(){rrt=false});hold('bT',function(){thr=true},function(){thr=false});
document.addEventListener('keydown',function(e){if(e.key==='ArrowLeft')rl=true;if(e.key==='ArrowRight')rrt=true;if(e.key==='ArrowUp'||e.key===' ')thr=true});document.addEventListener('keyup',function(e){if(e.key==='ArrowLeft')rl=false;if(e.key==='ArrowRight')rrt=false;if(e.key==='ArrowUp'||e.key===' ')thr=false});
`
