  splash: b => `<div class="dvm"><div class="hd"><span><small>BY. ${b}</small><b>DRONE VIEW</b><small>3D · OPEN WORLD</small></span><div class="cam">CAM<br>1</div></div><div class="map"><div class="sw"></div><div class="me"></div><div class="rd" style="left:0;top:60px;width:100%;height:14px"></div><div class="rd" style="left:120px;top:0;width:14px;height:100%"></div><div class="bd" style="left:20px;top:14px;width:40px;height:34px"></div><div class="bd" style="left:150px;top:90px;width:60px;height:40px"></div><div class="bd" style="left:250px;top:20px;width:34px;height:30px"></div><div class="bd" style="left:60px;top:100px;width:30px;height:36px"></div><div class="lb">MENCARI SINYAL ELANG-1 …</div></div><div class="tele"><div>ALT<b>0.0 m</b></div><div>SPD<b>0 km/h</b></div><div>PITCH<b>0°</b></div><div>BATT<b>100%</b></div></div><div style="margin-top:16px;text-align:center;font-size:12px;color:#7dd3fc;line-height:1.7">Dua tahun lalu, drone survei ayah Arka — <b style="color:#22d3ee">ELANG-1</b> — hilang bersama pilotnya.<br>Hari ini sinyalnya muncul lagi.<br><br><b style="color:#e0fbff">ketuk untuk menyalakan drone</b></div></div>`,
